export interface SellThroughComparisonCycle {
  cycle: number;
  date: string;
  venue: string;
}

export interface SellThroughComparisonResult {
  marketCycle: number;
  /** @minimum 0 */
  purchasedStems: number;
  /** @minimum 0 */
  leftoverStems: number;
  /** @minimum 0 */
  soldStems: number;
  /**
     * @minimum 0
     * @maximum 100
     */
  sellThroughPercent: number;
}

export interface SellThroughComparisonFlower {
  flower: string;
  results: SellThroughComparisonResult[];
}

export interface SellThroughComparison {
  cycles: SellThroughComparisonCycle[];
  flowers: SellThroughComparisonFlower[];
}

export type CloseMarketUpdateCounts = {[key: string]: number};

export interface CloseMarketUpdate {
  counts: CloseMarketUpdateCounts;
  closed: boolean;
  /** Explicitly authorize reopening a finalized close-market record for editing */
  reopen?: boolean;
  /** Optional contextual notes about weather, stall placement, or other market conditions */
  notes?: string | null;
}

export interface MarketContext {
  cycle: number;
  date: string;
  venue: string;
  spend: number;
  revenue: number;
  margin: number;
  buyItems: BuyItem[];
  buyList: MarketBuyListState;
  actualPurchases: ActualPurchase[];
  costs: MarketCost[];
  bouquetPlan: BouquetPlan;
  closeMarket: CloseMarket;
}

export type GetSellThroughComparisonParams = {
/**
 * Completed market cycles to compare
 * @minItems 1
 */
cycles: number[];
};

